import { Toolbar as AriaToolbar } from "react-aria-components";
import type { ToolbarProps as AriaToolbarProps } from "react-aria-components";
import type { ReactNode, Ref } from "react";
import { Separator } from "./Separator";
import type { SeparatorProps } from "./Separator";
import "./Toolbar.css";

export interface ToolbarBaseProps
  extends Omit<
    AriaToolbarProps,
    "className" | "children" | "orientation" | "aria-label" | "aria-labelledby"
  > {
  /**
   * Layout orientation of the toolbar.
   *
   * @default "horizontal"
   */
  orientation?: "horizontal" | "vertical";
  /** Toolbar controls. */
  children?: ReactNode;
  /** Additional class. sd-toolbar is always retained. */
  className?: string;
  /** Passed to the root toolbar DOM element. */
  ref?: Ref<HTMLDivElement>;
}

/**
 * A `role="toolbar"` has no visible label of its own, so it needs an accessible
 * name — `aria-label` or `aria-labelledby` is **required at the type level** (WAI-ARIA
 * toolbar pattern; same enforcement posture as Button's icon-only accessible name,
 * component-contract §2). This is the only reason `ToolbarProps` is a union, not an
 * interface.
 */
export type ToolbarProps =
  | (ToolbarBaseProps & { "aria-label": string })
  | (ToolbarBaseProps & { "aria-labelledby": string });

/* Chrome-less by design (§6 surface ownership): a Toolbar owns BEHAVIOUR — `role="toolbar"`,
   roving focus, orientation — not a surface. A floating control bar is composed, exactly as
   DatePicker gets its floating surface from `<PopoverContent>` and as BottomNav is built:
     <Card size="small" variant="raised"><Toolbar …>…</Toolbar></Card>
   with the Block owning the `position: fixed` that actually makes it float — see the
   `FloatingToolbar` Block, which is exactly that composition and is where its story lives. It previously carried a
   `variant="raised"` whose six chrome tokens resolved to EXACTLY the same Sys values as Card's
   small/raised tier (6/6, measured), so retuning one silently desynced the other; and that path
   could never finish the job anyway, since only a Block may position the bar. */
export function Toolbar({
  orientation = "horizontal",
  children,
  className,
  ref,
  ...props
}: ToolbarProps) {
  return (
    <AriaToolbar
      {...props}
      ref={ref}
      orientation={orientation}
      data-orientation={orientation}
      className={className ? `sd-toolbar ${className}` : "sd-toolbar"}
    >
      {children}
    </AriaToolbar>
  );
}

export interface ToolbarSeparatorProps extends Omit<SeparatorProps, "className" | "ref" | "variant"> {
  /** Additional class. sd-toolbar__separator is always retained. */
  className?: string;
  /**
   * Passed to the underlying separator DOM element. React Aria renders a vertical
   * separator as a `<div>` and a horizontal one as an `<hr>`, so the ref can be either.
   */
  ref?: Ref<HTMLHRElement | HTMLDivElement>;
}

/**
 * A divider between groups of controls in a Toolbar. Wraps the generic
 * `Separator` and insets it from the toolbar's cross-axis (via margin) so it
 * reads as a shorter, softer divider — the same wrapper pattern as `MenuSeparator`.
 */
export function ToolbarSeparator({ className, ...props }: ToolbarSeparatorProps) {
  return (
    <Separator
      {...props}
      className={className ? `sd-toolbar__separator ${className}` : "sd-toolbar__separator"}
    />
  );
}

.sd-toolbar {
  display: inline-flex;
  gap: var(--sd-toolbar-gap);
}

.sd-toolbar[data-orientation="vertical"] {
  flex-direction: column;
}

/* Controls of different heights (a Switch beside a Select beside a SegmentedControl) share one
   centre line instead of hanging from the top. A vertical ToolbarSeparator still spans the row: it
   sets its own `align-self: stretch`. A vertical toolbar keeps the default stretch, so its column of
   controls stays one width. */
.sd-toolbar[data-orientation="horizontal"] {
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
}

/* ToolbarSeparator: a divider set apart from the controls (mirrors the MenuSeparator
   wrapper-class pattern). Two independent margins — a small cross-axis `margin` insets the
   divider shorter than the row, and a larger main-axis `separator-gap` gives it breathing room
   from the adjacent groups. That token is the WHOLE group-to-rule distance, and the root `gap`
   already stands on each side of the divider, so the margin is the token net of the gap: the two
   never add (token-contract.md, bar-groups):
   - vertical divider (in a horizontal toolbar) uses `align-self: stretch`, so block margin
     shrinks the stretched height (inset) and inline margin adds the left/right group gap.
   - horizontal divider (in a vertical toolbar) uses `width: 100%` (+ flex-shrink:0), so inline
     margin can't inset it (would overflow) — it gets the block group gap only. */
/* The light decorative edge in place of Separator's 3:1 control edge: the groups are already told
   apart (ARIA groups, the gap), so the rule is punctuation. Keyed on `[data-orientation]`, present
   on both axes, so it outranks `.sd-separator` without relying on stylesheet order. */
.sd-toolbar__separator[data-orientation] {
  background: var(--sd-toolbar-separator-background);
}

.sd-toolbar__separator[data-orientation="vertical"] {
  margin-block: var(--sd-toolbar-separator-margin);
  margin-inline: calc(var(--sd-toolbar-separator-gap) - var(--sd-toolbar-gap));
}

.sd-toolbar__separator[data-orientation="horizontal"] {
  margin-block: calc(var(--sd-toolbar-separator-gap) - var(--sd-toolbar-gap));
}
